# tk Default Screen - curently testing and adjsuting...from tkinter import *from PIL import Image, ImageTkimport os# controling were code runs for dev, will need to change when ready for generic LIVE version...home = os.getcwd()if home.find('/')> -1:    #linux machine    os.chdir('/home/eric/Documents')else:    #my laptop    os.chdir('C:\\Users\\Owner\\Documents\\Python3 source code')# now running from /home/eric/java/js-basicshome = os.getcwd()print('home dir = {}'.format(home))class win(Frame):    def __init__(self, master = None):        Frame.__init__(self,master)        self.master = master        self.init_window()            def init_window(self):        self.master.title("TK Edit Window Template")        self.grid(row = 0)        #quitButton = Button(self, text = 'Quit', command=self.client_exit)        #quitButton.place(x=0, y=0)        menu = Menu(self.master)        self.master.config(menu=menu)        file = Menu(menu)        file.add_command(label='Save', command = self.saveWinFields)        file.add_command(label='Exit', command = self.client_exit)        menu.add_cascade(label='File', menu=file)                edit = Menu(menu)        #edit.add_command(label='Show Image',command=self.showImg)                edit.add_command(label='Print cb_mllp_var',command=self.printMllp)        edit.add_command(label='Show Text',command=self.printE1)        menu.add_cascade(label='Edit', menu=edit)                self.label_g1 = Label(self, text = "Generic Label 1", bg="white", fg='blue')        self.label_g1.grid(row = 1)        self.e1 = Entry(self)        self.e1.grid(row = 1, column = 2)        #sb1 = Scrollbar(self)  # Scroll Bar        self.tw1 = Text(self, height = 5, width = 65)  # Text Widget Out 1        #sb1.pack(side=RIGHT, fill=Y)        self.tw1.grid(row = 5, column = 10)        # self.tw1.insert(END, sd) moved to "Load Values section below"        # checkbox thinking for wrap message in mllp        self.cb_mllp_var = IntVar()        self.cb_mllp = Checkbutton(self, text="Wrap msg in mllp", variable = self.cb_mllp_var)        self.cb_mllp.grid(row = 4, column = 20)        self.errorLabel = Label(self,text = '',bg='red',fg='white')        # Load Values Section        # load in any save data (starting off just using a file)                ls = os.listdir()  # Array with current directoery (like the linux BASH command)        self.df = 'scndata'        self.twf = 'twfdata'        twd = ''  # Text Widget Data        totalerrors = ''        if self.df in ls:            fo = open(self.df,'rt')            sd = fo.read()  # Saved Data             fo.close()        else:            sd = 'self.cb_mllp_var.set(1)\nEND\n'            fo = open(self.df,'xt')            fo.write(sd)            fo.close        if self.twf in ls:            fo = open(self.twf,'rt')            twd = fo.read()            fo.close()        else:            twd = 'Default Text Widget data'            fo = open(self.twf,'tx')            fo.write(twd)            fo.close()        self.tw1.insert(END, twd)                    cl = ''  #Current Line        while cl != 'END':            p = sd.find('\n')            cl = sd[:p]            sd = sd[p+1:]            if cl != 'END':                try:                    eval(cl)                except ValueError as e:                    totalerrors = totalerrors + e                    self.errorLabel.text = totalerrors                    self.errorlabel.grid(row = 30)            def printMllp(self):        print('cb_mllp_var = {}'.format(self.cb_mllp_var.get()))            def printE1(self):        print('e1.get() = {}'.format(self.e1.get()))        def getSd(self):        return self.tw1.get("1.0",'end-1c')            def saveWinFields(self):        sd = ''        twv = self.tw1.get("1.0",'end-1c')        if len(twv) > 0:            fo = open(self.twf,'tw')            fo.write(twv)            fo.close()        e1v = self.e1.get()        if len(e1v)> 0:            sd = sd + 'self.e1.insert(0, "{}")\n'.format(e1v)        cbv = self.cb_mllp_var.get()        sd = sd + 'self.cb_mllp_var.set({})\n'.format(cbv)        sd = sd + 'END\n'        print('twv = {}'.format(twv))        print('saveWinText function triggered sd:\n{}'.format(sd))        fo = open(self.df,'wt')        fo.write(sd)        fo.close()                    def showImg(self):        load = Image.open('100k-moon.jpg.optimal.jpg')  # working image: i1.png        render = ImageTk.PhotoImage(load)        img = Label(self, image=render)        img.image = render        img.place(x=0,y=0)            def showTxt(self):        text = Label(self, text='Hi Resolution Moon Photo')        text.grid(row = 2, column = 15)  # "basically just adds the text"                    def client_exit(self):        exit()       root = Tk() root.geometry('1200x300')app = win(root)root.mainloop()